class NoticesResource(Resource):
    """``checkbox.notices``"""

    def list_due(self, params: Optional["types.ListDueNoticesParams"] = None, /, *, request_options: Optional[RequestOptions] = None, **kwargs: Any) -> "ListObject[types.DueNotice]":
        """List due notices.

        The legally required emails you owe subscribers (sites in "You send" mode, the default): kind, the subscriber (billing-platform ids), the legal window for the subscriber's state, the recommended send date, the copy-ready email and the BCC address. Default: everything not yet sent (upcoming, due, overdue), soonest first. Live keys list live subscribers' notices, test keys test-mode ones. Send each one on its send_date (inside its window), then call markNoticeSent (or BCC the notice's bcc address). Subscribe to the notice.due webhook to get each one on its send date.

        Parameters can be given as a dict (positional) or as keyword arguments.

        ``GET /v1/notices/due`` (operation ``listDueNotices``, scope ``notices:read``).
        """
        return self._call("listDueNotices", (), params, kwargs, request_options)  # type: ignore[no-any-return]

    def list_templates(self, params: Optional["types.ListNoticeTemplatesParams"] = None, /, *, request_options: Optional[RequestOptions] = None, **kwargs: Any) -> "types.NoticeTemplateList":
        """List notice email templates.

        Copy-ready HTML + text templates for every required notice (acknowledgment with and without a trial, trial ending, renewal, yearly terms, price change, cancellation confirmation), with {{merge_fields}}. Each passes the preflight email check for its kind when filled. Pass ?site= to get each kind's BCC address too. Adapt one, then call checkNoticeTemplate.

        Parameters can be given as a dict (positional) or as keyword arguments.

        ``GET /v1/notices/templates`` (operation ``listNoticeTemplates``, scope ``notices:read``).
        """
        return self._call("listNoticeTemplates", (), params, kwargs, request_options)  # type: ignore[no-any-return]

    def check_template(self, params: Optional["types.CheckNoticeTemplateParams"] = None, /, *, request_options: Optional[RequestOptions] = None, **kwargs: Any) -> "types.NoticeTemplateCheck":
        """Check a notice email template.

        Checks your own version of a notice email: Checkbox fills the merge fields with the site's plan, brand and cancel URL (sample dates), then runs the preflight email check for the kind across the site's jurisdictions. Stateless. Fix what fails (or start from listNoticeTemplates) and check again until verdict is pass.

        Parameters can be given as a dict (positional) or as keyword arguments.

        ``POST /v1/notices/templates/check`` (operation ``checkNoticeTemplate``, scope ``notices:read``).
        """
        return self._call("checkNoticeTemplate", (), params, kwargs, request_options)  # type: ignore[no-any-return]

    def retrieve(self, notice: str, /, *, request_options: Optional[RequestOptions] = None) -> "types.DueNotice":
        """Retrieve a due notice.

        One notice you owe a subscriber, with its window, recommended send date, copy-ready email, BCC address and send status.

        ``GET /v1/notices/{notice}`` (operation ``retrieveDueNotice``, scope ``notices:read``).
        """
        return self._call("retrieveDueNotice", (notice, ), None, None, request_options)  # type: ignore[no-any-return]

    def mark_sent(self, notice: str, params: Optional["types.MarkNoticeSentParams"] = None, /, *, request_options: Optional[RequestOptions] = None, **kwargs: Any) -> "types.DueNotice":
        """Mark a due notice as sent.

        Records that you sent this notice (optionally with your email provider's message id). Idempotent: a notice already marked sent is returned unchanged. A send before window_start is refused (it does not satisfy the law: send again inside the window). An overdue notice marked sent stops failing its check and is recorded as late; a sent_at earlier than when it became overdue is refused (only the BCC copy can prove an in-window send). Canceled and missed notices cannot be marked. BCC'ing the notice's bcc address does the same with the email itself as evidence.

        Parameters can be given as a dict (positional) or as keyword arguments.

        ``POST /v1/notices/{notice}/sent`` (operation ``markNoticeSent``, scope ``notices:write``).
        """
        return self._call("markNoticeSent", (notice, ), params, kwargs, request_options)  # type: ignore[no-any-return]

    def mark_missed(self, notice: str, params: Optional["types.MarkNoticeMissedParams"] = None, /, *, request_options: Optional[RequestOptions] = None, **kwargs: Any) -> "types.DueNotice":
        """Record a due notice as missed.

        Records that an overdue notice was not sent and will not be (for example, the subscriber already left). Nothing is attested as sent: the notice moves to missed and stops failing its compliance check, and the record stays in the history. Only overdue notices can be recorded as missed. Idempotent.

        Parameters can be given as a dict (positional) or as keyword arguments.

        ``POST /v1/notices/{notice}/missed`` (operation ``markNoticeMissed``, scope ``notices:write``).
        """
        return self._call("markNoticeMissed", (notice, ), params, kwargs, request_options)  # type: ignore[no-any-return]


