class EventsResource(Resource):
    """``checkbox.events``"""

    def list(self, params: Optional["types.ListEventsParams"] = None, /, *, request_options: Optional[RequestOptions] = None, **kwargs: Any) -> "ListObject[types.Event]":
        """List events.

        Events newest first. Poll with ending_before=<newest id you have> to get only new events (an alternative to webhooks).

        Parameters can be given as a dict (positional) or as keyword arguments.

        ``GET /v1/events`` (operation ``listEvents``, scope ``events:read``).
        """
        return self._call("listEvents", (), params, kwargs, request_options)  # type: ignore[no-any-return]

    def retrieve(self, event: str, /, *, request_options: Optional[RequestOptions] = None) -> "types.Event":
        """Retrieve an event.

        One event with its payload (data.object) and the number of webhook deliveries still pending.

        ``GET /v1/events/{event}`` (operation ``retrieveEvent``, scope ``events:read``).
        """
        return self._call("retrieveEvent", (event, ), None, None, request_options)  # type: ignore[no-any-return]


class FeedbacksResource(Resource):
    """``checkbox.feedbacks``"""

    def create(self, params: Optional["types.FeedbackParams"] = None, /, *, request_options: Optional[RequestOptions] = None, **kwargs: Any) -> "types.Feedback":
        """Send feedback.

        Report a problem or a missing feature in Checkbox. Include what you tried, what happened and what you expected, and the site / request id when there is one. With type review, send a structured review of Checkbox the product (score 0-10, liked, disliked, wrong_verdicts, would_keep_using, stack) — only after the human said yes and saw the text. A review describes what worked or did not in Checkbox: it never states that the site broke a law or had unfixed problems, and carries no site names, URLs, customer data or quotes of the site's pages or emails (URLs are removed and no site is attached). Never include secrets or customer data: anything that looks like a secret, card number or email address is replaced with [redacted]. The Checkbox team reads every message. Rate limited to 20 per key per hour.

        Parameters can be given as a dict (positional) or as keyword arguments.

        ``POST /v1/feedback`` (operation ``createFeedback``, scope ``account:read``).
        """
        return self._call("createFeedback", (), params, kwargs, request_options)  # type: ignore[no-any-return]


class ReviewPromptsResource(Resource):
    """``checkbox.review_prompts``"""

    def claim(self, site: str, params: Optional["types.ReviewPromptParams"] = None, /, *, request_options: Optional[RequestOptions] = None, **kwargs: Any) -> "types.ReviewPrompt":
        """Claim the one-time review prompt for a site.

        The MCP tools call this when a site's compliance plan reaches compliant (including "Compliant · N live checks pending"). show is true exactly once per site: the agent then asks the human once whether they want to send a quick review of Checkbox (createFeedback with type review), and sends it only on a yes, after showing the text. Never send a review without the human's yes.

        Parameters can be given as a dict (positional) or as keyword arguments.

        ``POST /v1/sites/{site}/review_prompt`` (operation ``claimReviewPrompt``, scope ``compliance_plans:read``).
        """
        return self._call("claimReviewPrompt", (site, ), params, kwargs, request_options)  # type: ignore[no-any-return]


